/**
 * A claim may be PENDING: a clerk settled it above the clerk limit and it waits for a steward to approve
 * (SETTLED) or reject (back to OPEN) it. The status's check is widened to allow it. H2 named that unnamed
 * check itself, so it is looked up here rather than in SQL. A PENDING claim keeps the statement binding it
 * had (stated, stated_due) but is not bound by it until it is rejected.
 */
public class V22__claim_pending extends BaseJavaMigration {
    @Override
    public void migrate(Context context) throws Exception {
        try (Statement st = context.getConnection().createStatement()) {
            List<String> checks = new ArrayList<>();
            try (ResultSet rs = st.executeQuery("SELECT t.CONSTRAINT_NAME FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS t"
                    + " JOIN INFORMATION_SCHEMA.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA = t.CONSTRAINT_SCHEMA"
                    + " AND c.CONSTRAINT_NAME = t.CONSTRAINT_NAME"
                    + " WHERE t.TABLE_NAME = 'CLAIM' AND t.CONSTRAINT_TYPE = 'CHECK' AND c.CHECK_CLAUSE LIKE '%STATUS%'")) {
                while (rs.next()) checks.add(rs.getString(1));
            }
            for (String check : checks) {
                st.execute("ALTER TABLE claim DROP CONSTRAINT \"" + check + "\"");
            }
            st.execute("ALTER TABLE claim ADD CONSTRAINT claim_status_check"
                    + " CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'))");
        }
    }
}
-- A claim's number is text: the sheet-wide 1, 2, ... or, while the period-numbering-from setting is in
-- force when the claim is opened, <period name>-<n> (X-<n> for a claim in no period). A correction names
-- the claim it corrects by that same text.
ALTER TABLE claim ALTER COLUMN claim_number VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(220);
-- The last number each period sequence of a sheet gave out. seq: the period's name in lower case, prefixed
-- 'P:', or 'X' for claims in no period. A sequence without a row has given out none.
CREATE TABLE claim_number_seq (
    sheet_id VARCHAR(100) NOT NULL,
    seq      VARCHAR(210) NOT NULL,
    last_n   INT          NOT NULL,
    PRIMARY KEY (sheet_id, seq)
);
-- A person's claims, listed newest first (by id, descending).
-- amount: 0.00 or more, two decimals; claim_date: defaults to the sheet's today; note: may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)  NOT NULL,
    person_id  BIGINT        NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE          NOT NULL,
    note       VARCHAR(1000) NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- The sheet's settings, by key. A key without a row is blank (for clerk-limit: no limit).
CREATE TABLE sheet_setting (
    sheet_id VARCHAR(100) NOT NULL,
    setting  VARCHAR(50)  NOT NULL,
    val      VARCHAR(100) NOT NULL,
    PRIMARY KEY (sheet_id, setting)
);
-- The role the sheet assigns a user name: clerk or steward. A name without a row is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(100) NOT NULL,
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);

